UPDATE sales_order
SET user_id = #{userId}, total_amount = #{totalAmount}, status = #{status}
WHERE order_id = #{orderId}

mapper.select:
SELECT *
FROM sales_order o
WHERE o.status = #{status}

SELECT o.order_id, o.user_id, o.total_amount, o.status, o.created_at, oi.order_item_id, oi.order_id, oi.product_id, oi.quantity, oi.price FROM sales_order o LEFT JOIN sales_order_item oi ON o.order_id = oi.order_id
1 = 1
AND o.user_id = #{userId}
AND o.status = #{status}
AND o.created_at >= #{startTime}
AND o.created_at <= #{endTime}

WITH paginated_orders AS ( SELECT o.order_id, o.user_id, o.total_amount, o.status, o.created_at FROM sales_order o
1 = 1
AND o.user_id = #{userId}
AND o.status = #{status}
AND o.created_at >= #{startTime}
AND o.created_at <= #{endTime}
AND ( o.created_at < #{cursorCreatedAt} OR (o.created_at = #{cursorCreatedAt} AND o.order_id < #{cursorOrderId}) )
ORDER BY o.created_at DESC, o.order_id DESC LIMIT #{limit} ) SELECT po.order_id, po.user_id, po.total_amount, po.status, po.created_at, oi.order_item_id, oi.order_id, oi.product_id, oi.quantity, oi.price FROM paginated_orders po LEFT JOIN sales_order_item oi ON po.order_id = oi.order_id ORDER BY po.created_at DESC, po.order_id DESC, oi.order_item_id ASC
